//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_interface_facts(value: *mut Isolette_Thermostat_Rust::MonitorInterfaceFacts) -> bool;
  fn get_diagnostic_facts(value: *mut Isolette_Thermostat_Rust::MonitorDiagnosticFacts) -> bool;
  fn put_mode_for_interface(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool;
  fn put_mode_for_alarm(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool;
}

pub fn unsafe_get_interface_facts() -> Isolette_Thermostat_Rust::MonitorInterfaceFacts
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::MonitorInterfaceFacts = &mut Isolette_Thermostat_Rust::MonitorInterfaceFacts::default();
    get_interface_facts(value);
    return *value;
  }
}

pub fn unsafe_get_diagnostic_facts() -> Isolette_Thermostat_Rust::MonitorDiagnosticFacts
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::MonitorDiagnosticFacts = &mut Isolette_Thermostat_Rust::MonitorDiagnosticFacts::default();
    get_diagnostic_facts(value);
    return *value;
  }
}

pub fn unsafe_put_mode_for_interface(value: &Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  unsafe {
    return put_mode_for_interface(value as *const Isolette_Thermostat_Rust::ThermostatMode as *mut Isolette_Thermostat_Rust::ThermostatMode);
  }
}

pub fn unsafe_put_mode_for_alarm(value: &Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  unsafe {
    return put_mode_for_alarm(value as *const Isolette_Thermostat_Rust::ThermostatMode as *mut Isolette_Thermostat_Rust::ThermostatMode);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_interface_facts: Mutex<Option<Isolette_Thermostat_Rust::MonitorInterfaceFacts>> = Mutex::new(None);
  pub static ref IN_diagnostic_facts: Mutex<Option<Isolette_Thermostat_Rust::MonitorDiagnosticFacts>> = Mutex::new(None);
  pub static ref OUT_mode_for_interface: Mutex<Option<Isolette_Thermostat_Rust::ThermostatMode>> = Mutex::new(None);
  pub static ref OUT_mode_for_alarm: Mutex<Option<Isolette_Thermostat_Rust::ThermostatMode>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_interface_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_diagnostic_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_mode_for_interface.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_mode_for_alarm.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_interface_facts(value: *mut Isolette_Thermostat_Rust::MonitorInterfaceFacts) -> bool
{
  unsafe {
    let guard = IN_interface_facts.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_diagnostic_facts(value: *mut Isolette_Thermostat_Rust::MonitorDiagnosticFacts) -> bool
{
  unsafe {
    let guard = IN_diagnostic_facts.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_mode_for_interface(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  unsafe {
    *OUT_mode_for_interface.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_mode_for_alarm(value: *mut Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  unsafe {
    *OUT_mode_for_alarm.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
